import{_ as n}from"./chunks/image40.bIdiuhOZ.js";import{_ as o}from"./chunks/image11.B6ai34I9.js";import{_ as i}from"./chunks/image10.CXG-iZ2X.js";import{_ as r}from"./chunks/image51.Cad02_SZ.js";import{_ as s}from"./chunks/2.BRgDBKom.js";import{_ as c,o as l,c as d,am as p}from"./chunks/framework.CenUaW7a.js";const e="/projects/AiMechaM1/en/advanced-kit/assets/7.1.B_GjL_jc.webp",a="/projects/AiMechaM1/en/advanced-kit/assets/7.2.CdmeMTbG.webp",m="/projects/AiMechaM1/en/advanced-kit/assets/image49.DcY5kF3R.png",h="/projects/AiMechaM1/en/advanced-kit/assets/image50.DwBnJuLa.png",g="/projects/AiMechaM1/en/advanced-kit/assets/image52.By_8v_fD.png",u="/projects/AiMechaM1/en/advanced-kit/assets/image53.1-0Uv2fq.png",f="/projects/AiMechaM1/en/advanced-kit/assets/image54.DNS0Yx_C.png",T=JSON.parse('{"title":"3.7 Lesson 7: Basic Path Planning","description":"","frontmatter":{},"headers":[],"relativePath":"docs/3. Course materials/3.7 Lesson 7 Basic Path Planning.md","filePath":"docs/3. Course materials/3.7 Lesson 7 Basic Path Planning.md"}'),y={name:"docs/3. Course materials/3.7 Lesson 7 Basic Path Planning.md"};function b(w,t,_,v,x,P){return l(),d("div",null,[...t[0]||(t[0]=[p('<h1 id="_3-7-lesson-7-basic-path-planning" tabindex="-1">3.7 Lesson 7: Basic Path Planning <a class="header-anchor" href="#_3-7-lesson-7-basic-path-planning" aria-label="Permalink to &quot;3.7 Lesson 7: Basic Path Planning&quot;">​</a></h1><h2 id="_3-7-1-lesson-introduction" tabindex="-1">3.7.1 Lesson Introduction <a class="header-anchor" href="#_3-7-1-lesson-introduction" aria-label="Permalink to &quot;3.7.1 Lesson Introduction&quot;">​</a></h2><p>Building upon single-direction motion control, this lesson introduces fundamental path planning. Taking inspiration from Z-turn skiing, a Z-shaped trajectory is simulated to illustrate multi-segment motion combinations. Following the progression of &quot;single segments → two-segment connections → multi-segment combinations → loop paths&quot;, translational and diagonal movement commands are reviewed to complete a Z-turn by connecting straight and diagonal segments, which is then expanded to closed square trajectories and continuous loop motion. Movement commands with distance parameters are introduced to advance from time-based control to distance-based control. Mastering basic path planning establishes sequential arrangement thinking for advanced autonomous navigation.</p><h2 id="_3-7-2-learning-objectives" tabindex="-1">3.7.2 Learning Objectives <a class="header-anchor" href="#_3-7-2-learning-objectives" aria-label="Permalink to &quot;3.7.2 Learning Objectives&quot;">​</a></h2><p><strong>1.</strong> Understand the basic concepts of path planning and the principles of connecting multi-segment movements. Master the mechanism of how distance parameters affect path accuracy. Learn the kinematic relationship among rotational speed, time, and distance.</p><p><strong>2.</strong> Precisely control single-segment displacement length using movement commands with distance parameters. Master the combination and connection methods of angular diagonal movement and translational movement commands. Independently complete the full path program for a Z-shaped turn.</p><p><strong>3.</strong> Cultivate the ability to decompose complex trajectories into simple straight-line segments. Strengthen engineering awareness of parameterized design and precision control. Form an initial practical mindset for closed-loop debugging and parameter calibration.</p><p><strong>4.</strong> Connect path planning to industrial logistics and warehousing scenarios. Understand the core value of trajectory planning technology in smart manufacturing and unmanned warehousing. Stimulate interest in exploring robot navigation and motion planning technologies.</p><h2 id="_3-7-3-preparation" tabindex="-1">3.7.3 Preparation <a class="header-anchor" href="#_3-7-3-preparation" aria-label="Permalink to &quot;3.7.3 Preparation&quot;">​</a></h2><p><strong>Hardware Preparation:</strong></p><ul><li>AiMecha M1 Mecanum-wheel robot base × 1</li><li>Type-C USB data cable × 1</li><li>Computer running Windows or macOS × 1</li></ul><p><strong>Software Preparation:</strong></p><ul><li>WonderLab graphical programming platform installed and running normally</li></ul><p><strong>Z-Shaped Path Parameter Table</strong>: Segment ① is a 40 cm straight translation to the right. Segment ② is a diagonal connecting movement in the 135° direction. Segment ③ is a 40 cm straight translation to the right. Setting the standard teaching demonstration rotational speed to 50 rpm is recommended to balance motion smoothness and path accuracy.</p><p><strong>Device Connection Description</strong>: Connect the mecha controller to the computer using a Type-C data cable. The four motors are pre-wired at the factory. Movement commands with distance parameters incorporate built-in encoder feedback, providing higher distance accuracy than pure timed control, though actual performance is still affected by ground friction conditions, so fine-tuning parameters after field testing is recommended.</p><h2 id="_3-7-4-hands-on-project" tabindex="-1">3.7.4 Hands-On Project <a class="header-anchor" href="#_3-7-4-hands-on-project" aria-label="Permalink to &quot;3.7.4 Hands-On Project&quot;">​</a></h2><p><strong>1. Project Analysis</strong></p><p>This project focuses on Z-shaped path planning for the Mecanum-wheel car, adopting a three-layer control logic of &quot;path decomposition → segmented execution → sequential connection&quot;. Path decomposition splits the Z-shaped trajectory into two lateral translations and one diagonal connection. Segmented execution calls parameterized movement commands to precisely control the direction and displacement of each segment. Sequential connection relies on a sequential structure to execute each segment in order with smooth transitions. Leveraging the omnidirectional movement characteristics of the Mecanum-wheel car, the front orientation of the car remains unchanged throughout the entire process, completing the Z-shaped maneuver without turning the chassis. This demonstrates the path planning advantages of an omnidirectional platform, where complex geometric trajectories such as squares can also be achieved by combining multiple basic motion segments.</p><img loading="lazy" height="540" width="960" src="'+e+'" class="common_img" style="width:600px;aspect-ratio:960 / 540;"><img loading="lazy" height="540" width="960" src="'+a+'" class="common_img" style="width:600px;aspect-ratio:960 / 540;"><p>💡<strong>Complete Program Preview:</strong></p><img loading="lazy" height="449" width="1159" src="'+m+'" class="common_img" style="width:300px;aspect-ratio:1159 / 449;"><p><strong>2. Core Commands</strong></p><table tabindex="0"><thead><tr><th style="text-align:center;">Command Category</th><th style="text-align:center;">Core Command</th><th style="text-align:left;">Functional Description</th></tr></thead><tbody><tr><td style="text-align:center;">Distance movement</td><td style="text-align:center;"><img loading="lazy" height="61" width="523" src="'+h+'" class="common_img" style="width:100px;aspect-ratio:523 / 61;"></td><td style="text-align:left;">Translational movement command with a distance parameter to precisely control movement direction and displacement length.</td></tr><tr><td style="text-align:center;">Angular movement</td><td style="text-align:center;"><img loading="lazy" height="64" width="522" src="'+n+'" class="common_img" style="width:100px;aspect-ratio:522 / 64;"></td><td style="text-align:left;">Controls diagonal movement in any direction via an angle parameter, used for connecting path segments.</td></tr><tr><td style="text-align:center;">Loop control</td><td style="text-align:center;"><img loading="lazy" height="276" width="415" src="'+o+'" class="common_img" style="width:100px;aspect-ratio:415 / 276;"></td><td style="text-align:left;">Infinite loop structure used to achieve continuous reciprocating motion along a path trajectory.</td></tr><tr><td style="text-align:center;">Timing control</td><td style="text-align:center;"><img loading="lazy" height="100" width="326" src="'+i+'" class="common_img" style="width:100px;aspect-ratio:326 / 100;"></td><td style="text-align:left;">Sets the pause duration between segments for brief stops at path turning points.</td></tr><tr><td style="text-align:center;">Event trigger</td><td style="text-align:center;"><img loading="lazy" height="161" width="424" src="'+r+'" class="common_img" style="width:100px;aspect-ratio:424 / 161;"></td><td style="text-align:left;">Triggers the program via button events, allowing different buttons to launch different paths.</td></tr></tbody></table><p><strong>3. Complete Program Description</strong></p><p><strong>Task 1: Single-Segment Straight Translational Path</strong></p><ul><li><p>Use the <code>When the A key is pressed briefly</code> block as the program trigger entry.</p></li><li><p>Add the <code> Move mecanum 40 cm toward Right at 50 RPM</code> command.</p></li></ul><img loading="lazy" height="121" width="521" src="'+g+'" class="common_img" style="width:300px;aspect-ratio:521 / 121;"><p><strong>Task 2: Complete Z-Shaped Path</strong></p><ul><li><p>Program entry: When the A key is pressed briefly.</p></li><li><p>Segment ① straight path: Set the Mecanum-wheel robot to move right for 40 cm at 50 rpm to complete the first lateral translation.</p></li><li><p>Add a brief wait command as an optional pause at the turning point.</p></li><li><p>Segment ② diagonal path: Set the Mecanum-wheel car to move in the 135° direction at 50 rpm to complete the diagonal cornering connection.</p></li><li><p>Add a brief wait command as an optional pause.</p></li><li><p>Segment ③ straight path: Set the Mecanum-wheel car to move right for 40 cm at 50 rpm to complete the second lateral translation.</p></li><li><p>Overall outcome: The car moves along a Z-shaped trajectory while keeping its front orientation unchanged throughout the entire process, completing the cornering maneuver without chassis rotation.</p></li><li><p>Key parameters: The 135° angle corresponds to rear-right diagonal movement, serving as the diagonal angle connecting the upper and lower parallel straight paths.</p></li></ul><img loading="lazy" height="357" width="683" src="'+u+'" class="common_img" style="width:300px;aspect-ratio:683 / 357;"><img loading="lazy" height="540" width="960" src="'+e+'" class="common_img" style="width:300px;aspect-ratio:960 / 540;"><p><strong>Extended Task: Closed Square Path and Loop Motion</strong></p><ul><li><p>Path composition: Move forward 40 cm → move right 40 cm → move backward 40 cm → and move left 40 cm, connecting four equal-length translational segments end to end.</p></li><li><p>Use the <code>set Mecanum-wheel car to move in the direction for 40 cm at 50 rpm</code> command for each segment.</p></li><li><p>After executing the four segments sequentially, the car returns near the starting point, forming a closed square trajectory with a side length of 40 cm.</p></li><li><p>Nest a <code>forever</code> loop block on the outer layer to achieve continuous loop motion along the square trajectory, making the car travel around the square repeatedly.</p></li><li><p>Design key point: Pay attention to the correspondence between the initial orientation of the car and the movement directions, as different starting orientations require different directional commands.</p></li></ul><img loading="lazy" height="520" width="722" src="'+f+'" class="common_img" style="width:300px;aspect-ratio:722 / 520;"><img loading="lazy" height="540" width="960" src="'+a+'" class="common_img" style="width:300px;aspect-ratio:960 / 540;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The program source files can be downloaded from <a href="https://drive.google.com/drive/folders/1vQnjkHE58XJU_cquYayobwkfJD5ZQ1KT?usp=sharing" target="_blank" rel="noreferrer">Program Files/Basic Path Planning</a>.</strong></p></div><p><strong>Program Upload</strong>:</p><ul><li><p>Step 1: Power on the mecha controller and insert the Type-C data cable into the data port above the power switch on the controller.</p></li><li><p>Step 2: Connect the other end of the data cable to a USB port on the computer.</p></li><li><p>Step 3: Click the <strong>Connect device</strong> button at the top of the software interface and select the COM port corresponding to CH340 from the port list.</p></li><li><p>Step 4: Click the upload button in the upper-right corner to download the compiled program to the mecha controller for execution.</p></li></ul><img loading="lazy" height="508" width="960" src="'+s+'" class="common_img" style="width:600px;aspect-ratio:960 / 508;"><h2 id="_3-7-5-expansion-and-advancement" tabindex="-1">3.7.5 Expansion and Advancement <a class="header-anchor" href="#_3-7-5-expansion-and-advancement" aria-label="Permalink to &quot;3.7.5 Expansion and Advancement&quot;">​</a></h2><p><strong>Project 1: Figure-8 Path Planning</strong></p><p>Building upon the Z-shaped and square trajectories, design a complex figure-8 path. Utilize basic motion segments such as translation and diagonal movement to plan two interconnected loop trajectories so that the car traces the shape of the number &quot;8&quot;. Carefully plan the direction, distance, and connecting angle of each segment to practice path decomposition and spatial geometric visualization, and optionally add a loop block to achieve continuous figure-8 movement.</p><p><strong>Project 2: Path Accuracy Calibration Experiment</strong></p><p>Design a comparative experiment to test the actual movement deviation when setting a 40 cm target distance at three different rotational speeds: 30 rpm, 50 rpm, and 70 rpm. Record the error data at different rotational speeds, analyze how rotational speed affects distance control accuracy, and identify the optimal rotational speed range with the highest precision. Cultivate scientific literacy in experimental measurement and data analysis, and understand the importance of parameter calibration in engineering.</p><h2 id="_3-7-6-q-a" tabindex="-1">3.7.6 Q&amp;A <a class="header-anchor" href="#_3-7-6-q-a" aria-label="Permalink to &quot;3.7.6 Q&amp;A&quot;">​</a></h2><p><strong>Q1: What is path planning?</strong></p><p><strong>Answer</strong>: Path planning is the process of pre-planning the motion trajectory a robot takes from a starting point to a target point according to task objectives, and breaking it down into a sequence of executable motion commands. Simply put, it means designing the route the robot needs to travel and translating it into a program so that it follows that route.</p><p><strong>Q2: Between movement blocks with distance parameters and controlling distance via wait time, which method is better?</strong></p><p><strong>Answer</strong>: Movement commands with distance parameters are generally superior to time-based control, offering higher precision and reliability, though each method has its own applicable scenarios.</p><h2 id="_3-7-7-technical-support-and-discussion" tabindex="-1">3.7.7 Technical Support and Discussion <a class="header-anchor" href="#_3-7-7-technical-support-and-discussion" aria-label="Permalink to &quot;3.7.7 Technical Support and Discussion&quot;">​</a></h2><p>Join the forum for sharing questions, ideas, or suggestions, and answers will be provided promptly. Click the hyperlink <a href="http://forum.hiwonder.com" target="_blank" rel="noreferrer">Hiwonder Forum</a> or enter the URL in a browser: <a href="http://forum.hiwonder.com" target="_blank" rel="noreferrer">http://forum.hiwonder.com</a></p>',52)])])}const A=c(y,[["render",b]]);export{T as __pageData,A as default};
